"""generates the 'iw.db' and 'rdns.db' files to be consumed by BIND"""

import datetime
import ipaddress
import os
import re
import sys
from pathlib import Path

from rpsl import DATA_DIR, RegistryObject

HEADER = """; This file was autogenerated by utils/generate_zone.py
; Do not edit! It will be regenerated.
$ORIGIN {origin}
$TTL 1h
@ IN SOA v.root-servers.iw. contact.itsvic.dev. {serial} 1h 15m 4d 30m

"""
SERIAL_RE = re.compile(r"^@ IN SOA \S+ \S+ (\d+) ", re.MULTILINE)
LABEL = r"(?!-)[a-z0-9-]{1,63}(?<!-)"
DOMAIN_RE = re.compile(rf"(?:{LABEL}\.)*iw", re.IGNORECASE)
DS_RE = re.compile(r"\d+ \d+ \d+ [0-9a-f]+", re.IGNORECASE)
RDNS_NET = ipaddress.IPv4Network("10.0.0.0/8")

problems: list[str] = []


def warn(path: Path, message: str):
    problems.append(f"{path.relative_to(DATA_DIR)}: {message}")


def load_objects(kind: str):
    for path in sorted((DATA_DIR / kind).iterdir()):
        try:
            yield path, RegistryObject.load(path)
        except ValueError as error:
            warn(path, str(error))


def forward_records() -> tuple[list[str], list[str]]:
    delegations, ds_records, glue = set(), set(), {}
    apex_ns = []
    for path, obj in load_objects("dns"):
        domain = obj.get("domain")
        if domain != path.name:
            warn(path, f"domain {domain!r} does not match the file name")
            continue
        if not DOMAIN_RE.fullmatch(domain):
            warn(path, f"{domain!r} is not a valid .iw domain")
            continue

        for nserver in obj.get_all("nserver"):
            host, *addrs = nserver.split()
            if not DOMAIN_RE.fullmatch(host) or len(addrs) > 1:
                warn(path, f"bad nserver {nserver!r}")
                continue
            try:
                addrs = [str(ipaddress.IPv4Address(addr)) for addr in addrs]
            except ValueError:
                warn(path, f"bad nserver address in {nserver!r}")
                continue
            delegations.add((domain, host))
            if domain == "iw":
                apex_ns.append(host)
            for addr in addrs:
                glue.setdefault(host, set()).add(addr)

        # iw. has no parent zone, so its ds-rdata is documentation only
        if domain == "iw":
            continue
        for rdata in obj.get_all("ds-rdata"):
            if not DS_RE.fullmatch(rdata):
                warn(path, f"bad ds-rdata {rdata!r}")
                continue
            ds_records.add((domain, rdata))

    for host, addrs in glue.items():
        if len(addrs) > 1:
            problems.append(f"conflicting glue for {host}: {', '.join(sorted(addrs))}")

    records = [f"{domain}. IN NS {host}." for domain, host in sorted(delegations)]
    records += [f"{domain}. IN DS {rdata}" for domain, rdata in sorted(ds_records)]
    records.append("")
    records += [f"{host}. IN A {addr}" for host in sorted(glue) for addr in sorted(glue[host])]
    return records, sorted(apex_ns)


def reverse_records(apex_ns: list[str]) -> list[str]:
    delegations = set()
    for path, obj in load_objects("inetnum"):
        nservers = obj.get_all("nserver")
        if not nservers:
            continue
        try:
            network = ipaddress.IPv4Network(obj.get("cidr") or "")
        except ValueError:
            warn(path, f"bad cidr {obj.get('cidr')!r}")
            continue
        if path.name != str(network).replace("/", "_"):
            warn(path, f"cidr {network} does not match the file name")
            continue
        if network.prefixlen != 24 or not network.subnet_of(RDNS_NET):
            warn(path, "reverse DNS is only delegated for /24s in 10.0.0.0/8")
            continue
        for host in nservers:
            if not DOMAIN_RE.fullmatch(host):
                warn(path, f"bad nserver {host!r}")
                continue
            delegations.add((network, host))

    records = [f"@ IN NS {host}." for host in apex_ns]
    for network, host in sorted(delegations):
        name = ".".join(reversed(str(network.network_address).split(".")[1:3]))
        records.append(f"{name} IN NS {host}.")
    return records


def render(origin: str, serial: int, records: list[str]) -> str:
    return HEADER.format(origin=origin, serial=serial) + "".join(f"{r}\n" for r in records)


def write_zone(path: Path, origin: str, records: list[str]) -> bool:
    old = path.read_text() if path.exists() else ""
    match = SERIAL_RE.search(old)
    old_serial = int(match[1]) if match else 0
    if render(origin, old_serial, records) == old:
        return False

    today = int(datetime.date.today().strftime("%Y%m%d00"))
    tmp = path.with_name(f"{path.name}.tmp")
    tmp.write_text(render(origin, max(old_serial + 1, today), records))
    os.replace(tmp, path)
    return True


def main() -> int:
    forward, apex_ns = forward_records()
    reverse = reverse_records(apex_ns)
    for problem in problems:
        print(f"warning: {problem}", file=sys.stderr)

    for path, origin, records in (
        (Path("iw.db"), "iw.", forward),
        (Path("rdns.db"), "10.in-addr.arpa.", reverse),
    ):
        changed = write_zone(path, origin, records)
        print(f"{path}: {'updated' if changed else 'unchanged'}")
    return 1 if problems else 0


if __name__ == "__main__":
    sys.exit(main())
